"""Write the artist handoff and coverage/duration index from installed races."""
import json
from pathlib import Path
ROOT=Path('data/campaigns/america/state-expansion')
entries=[r for r in json.loads(Path('data/campaigns/america/raceways/catalog.json').read_text()) if r['id'].startswith(('city-','state-'))]
assert len(entries)==79,'Install all 79 reviewed events before publishing the handoff'
cities=[r for r in entries if r.get('city')];assert len(cities)==50
notes=[json.loads((ROOT/'landmarks'/f"{r['stateCode']}.json").read_text()) for r in sorted(cities,key=lambda r:r['stateCode'])]
summary={'addedEvents':79,'stateGapEvents':29,'cityRuns':50,'landmarks':200,'coveredStates':sorted({r['stateCode'] for r in cities}),'navigation':'Choose a campaign location, then City Runs, Road Runs, Detours, or Raceways. Each optional event is assigned to its nearest main campaign location. Existing main progression is unchanged.','durationModel':'Curvature-limited winter planning pace, not a measured AI lap; car, conditions and driver change the result. Circuit estimates include all three laps.','limitations':['Road centerlines and tagged lane widths come from OpenStreetMap; missing widths use the existing importer defaults. These are not surveyed racing surfaces.','DEM ground elevations are approximate; mapped bridge decks interpolate between approaches. Coastal terrain-only DEM no-data uses sea level and is listed in each affected source document.','City races are fictional closed-road events following mapped local streets and one-way directions; turn-restriction relations and temporary construction are not modeled.','Landmark distances are nearest-road projections on the native timed route. Existing generic buildings dress cities; the 200 landmark-specific graphics have not been created.','Untimed approaches/runouts are explicitly authored fictional service roads, not additional surveyed GPS geometry.'],'events':[{'id':r['id'],'name':r.get('displayName',r['name']),'state':r['state'],'stateCode':r['stateCode'],'city':r.get('city'),'location':r.get('location'),'category':'City Runs' if r.get('city') else 'Raceways' if r['kind']=='circuit' else 'Detours' if any(s not in ('asphalt','wet-asphalt','concrete','paved') for s in r['installedSurfaces']) else 'Road Runs','hubStage':r['hubStage'],'hubRaceRef':r['hubRaceRef'],'raceRef':r['raceRef'],'documentPath':'data/server-storage/files/'+r['documentPath'],'mappedLengthMiles':round(r['lengthM']/1609.344,2),'laps':r['laps'],'estimatedMinutes':round(r['estimatedDrivingSeconds']/60,1),'references':r['references'],'landmarkNotes':str(ROOT/'landmarks'/f"{r['stateCode']}.json") if r.get('city') else None} for r in sorted(entries,key=lambda r:(r['stateCode'],r['id']))]}
(ROOT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
handoff={'purpose':'Create recognizable landmark doodad artwork for the 50 mapped city runs. Import definitions and source geometry are already installed; do not move roads to match artwork.','placement':'Use each landmark worldX/worldZ and side/offset as reference. Mileage is measured from the timed start. Inspect sightlines before placing a final sprite; keep collision outside the driveable road.','style':'Match existing pixel-art perspective and palette. Abandoned/frozen post-apocalyptic 2994 setting; preserve recognizable architecture. Transparent backgrounds, grounded bottom edge, no baked UI or mileage labels.','landmarkCount':sum(len(n['landmarks']) for n in notes),'cities':notes}
assert handoff['landmarkCount']==200
Path('AI/last-on-the-grid/state-expansion-landmark-artwork.json').write_text(json.dumps(handoff,indent=2)+'\n')
print('Wrote 79-event coverage index and 200-landmark artwork handoff.')
